package lt.viko.eif.imazolevska.rehearsalbooking.repository;

import lt.viko.eif.imazolevska.rehearsalbooking.entity.Room;
import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Repository for reading and saving rooms.
 * The implementation is generated by Spring Data JPA.
 */
public interface RoomRepository extends JpaRepository<Room, Long> {
    /**
     * Checks whether a room with the given name already exists.
     *
     * @param name the room name
     * @return true if a room with this name exists
     */
    boolean existsByName(String name);

}
